        instruction_derja: 'Farre9 el 3dham. Zid el sfour wa7ed wa7ed lel chocolat el dafi w khallat bel fesse5: lazem yob9a yelma3.',
        instruction_ar: 'افصل البيض وأضف الصفار واحداً تلو الآخر إلى الشوكولاتة الدافئة مع الخلط السريع حتى يبقى الخليط لامعاً.',
